128: function iconShell(inner, glow = '#d8f36a') {
129:   return `<svg viewBox="0 0 48 50" aria-hidden="true" focusable="false"><rect width="48" height="50" fill="#111613"/><ellipse cx="24" cy="25" rx="21" ry="24" fill="${glow}" opacity=".075"/><path d="M3 6V3h3M42 3h3v3M45 44v3h-3M6 47H3v-3" stroke="#d8f36a" stroke-opacity=".26" fill="none"/>${inner}</svg>`;
130: }
131: function metalRect(x, y, w, h, color, rx = 2) {
132:   const hi = Math.max(1.4, w * .2), lo = Math.max(1.2, w * .16);
133:   return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${color}"/><rect x="${x + 1.1}" y="${y + 1}" width="${hi}" height="${h - 2}" fill="#fff" opacity=".16"/><rect x="${x + w - lo - 1.1}" y="${y + 1}" width="${lo}" height="${h - 2}" fill="#000" opacity=".24"/>`;
134: }
135: function barrelIcon(profile, color, accent, x, y, w, h) {
136:   let out = '';
137:   if (profile === 'slim') { x += w * .2; w *= .6; }
138:   if (profile === 'taper') {
139:     out += `<path d="M${x + w * .24} ${y}H${x + w * .76}L${x + w} ${y + h}H${x}Z" fill="${color}"/>`;
140:     out += `<path d="M${x + w * .24} ${y}H${x + w * .4}L${x + w * .18} ${y + h}H${x}Z" fill="#fff" opacity=".15"/>`;
141:     out += `<path d="M${x + w * .76} ${y}H${x + w * .62}L${x + w * .84} ${y + h}H${x + w}Z" fill="#000" opacity=".22"/>`;
142:   } else if (profile === 'hex') {
143:     out += `<path d="M${x + w * .2} ${y}H${x + w * .8}L${x + w} ${y + h * .12}V${y + h * .88}L${x + w * .8} ${y + h}H${x + w * .2}L${x} ${y + h * .88}V${y + h * .12}Z" fill="${color}"/>`;
144:     out += `<path d="M${x + w * .2} ${y}H${x + w * .5}V${y + h}H${x + w * .2}L${x} ${y + h * .88}V${y + h * .12}Z" fill="#fff" opacity=".14"/>`;
145:     out += `<path d="M${x + w * .5} ${y}H${x + w * .8}L${x + w} ${y + h * .12}V${y + h * .88}L${x + w * .8} ${y + h}H${x + w * .5}Z" fill="#000" opacity=".2"/>`;
146:     out += `<path d="M${x + w * .2} ${y}H${x + w * .5}M${x + w * .2} ${y + h}H${x + w * .5}" stroke="#fff" stroke-opacity=".24"/>`;
147:   } else if (profile === 'stacked') {
148:     for (let i = 0; i < 4; i++) {
149:       const sw = w - i * 1.2, sx = x + (w - sw) / 2, sy = y + i * h / 4;
150:       out += `<rect x="${sx}" y="${sy}" width="${sw}" height="${h / 4 + .4}" rx="1.5" fill="${i % 2 ? color : accent}" opacity="${i % 2 ? 1 : .55}"/>`;
151:       out += `<rect x="${sx + 1}" y="${sy + 1}" width="2" height="${h / 4 - 2}" fill="#fff" opacity=".14"/>`;
152:     }
153:   } else {
154:     out += `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="2.2" fill="${color}"/>`;
155:     out += `<rect x="${x + 1.2}" y="${y + 1}" width="${Math.max(1.6, w * .2)}" height="${h - 2}" fill="#fff" opacity=".16"/>`;
156:     out += `<rect x="${x + w - Math.max(1.5, w * .16) - 1.2}" y="${y + 1}" width="${Math.max(1.5, w * .16)}" height="${h - 2}" fill="#000" opacity=".23"/>`;
157:   }
158:   if (profile === 'fluted') {
159:     for (let i = 0; i < 5; i++) out += `<rect x="${x + w * (.16 + i * .17)}" y="${y + 2}" width="1.2" height="${h - 4}" rx=".6" fill="${accent}" opacity=".8"/>`;
160:   } else if (profile === 'segmented') {
161:     for (let i = 0; i < 5; i++) out += `<rect x="${x - 1}" y="${y + 3 + i * (h - 6) / 5}" width="${w + 2}" height="2.6" rx="1.3" fill="${i % 2 ? accent : '#202623'}"/>`;
162:   } else if (profile === 'bulbous') {
163:     out += `<ellipse cx="${x + w / 2}" cy="${y + h / 2}" rx="${w * .62}" ry="${h * .27}" fill="${color}"/>`;
164:     out += `<ellipse cx="${x + w * .38}" cy="${y + h * .46}" rx="${w * .13}" ry="${h * .2}" fill="#fff" opacity=".14"/>`;
165:     out += `<rect x="${x - 1}" y="${y + 3}" width="${w + 2}" height="2" rx="1" fill="${accent}" opacity=".85"/>`;
166:     out += `<rect x="${x - 1}" y="${y + h - 5}" width="${w + 2}" height="2" rx="1" fill="${accent}" opacity=".85"/>`;
167:   }
168:   return out;
169: }
